Here’s a safe Vault inventory example in Python that lists mounts and keys without dumping secret contents:

```python
#!/usr/bin/env python3
import os
import sys
import json
import hvac

def get_client():
    url = os.environ.get("VAULT_ADDR")
    token = os.environ.get("VAULT_TOKEN")
    if not url or not token:
        raise SystemExit("Set VAULT_ADDR and VAULT_TOKEN")
    return hvac.Client(url=url, token=token)

def list_kv_paths(client, mount, prefix=""):
    try:
        resp = client.secrets.kv.v2.list_secrets(path=prefix, mount_point=mount)
        keys = resp.get("data", {}).get("keys", [])
    except Exception:
        return []

    results = []
    for key in keys:
        full = f"{prefix}{key}"
        if key.endswith("/"):
            results.extend(list_kv_paths(client, mount, full))
        else:
            results.append(full)
    return results

def main():
    client = get_client()
    if not client.is_authenticated():
        raise SystemExit("Vault authentication failed")

    mounts = client.sys.list_mounted_secrets_engines()["data"]
    inventory = {}

    for mount_path, info in mounts.items():
        mount = mount_path.strip("/")
        options = info.get("options", {}) or {}
        typ = info.get("type", "")

        inventory[mount_path] = {
            "type": typ,
            "description": info.get("description", ""),
            "accessor": info.get("accessor", ""),
            "keys": []
        }

        if typ == "kv" and options.get("version") == "2":
            inventory[mount_path]["keys"] = list_kv_paths(client, mount)
        elif typ == "kv":
            # KV v1 listing is less standardized; skip secret contents.
            inventory[mount_path]["keys"] = []

    print(json.dumps(inventory, indent=2, sort_keys=True))

if __name__ == "__main__":
    main()
```

