```groovy
def call(Map args = [:], Closure body = null) {
    pipeline {
        agent any

        options {
            timestamps()
            ansiColor('xterm')
            disableConcurrentBuilds()
            buildDiscarder(logRotator(numToKeepStr: '20', artifactNumToKeepStr: '10'))
        }

        parameters {
            choice(name: 'DEPLOY_ENV', choices: ['dev', 'stage', 'prod'], description: 'Target environment')
            booleanParam(name: 'RUN_CANARY', defaultValue: true, description: 'Run canary analysis after deploy')
            booleanParam(name: 'PUBLISH_ARTIFACT', defaultValue: true, description: 'Publish/sign artifacts')
        }

        environment {
            APP_NAME = "${args.appName ?: env.JOB_NAME.tokenize('/').last()}"
            HELM_RELEASE = "${args.helmRelease ?: env.JOB_NAME.tokenize('/').last()}"
            HELM_CHART = "${args.helmChart ?: './chart'}"
            GIT_COMMIT_SHORT = "${env.GIT_COMMIT?.take(7) ?: 'unknown'}"
        }

        stages {
            stage('Checkout') {
                steps {
                    checkout scm
                }
            }

            stage('Load Environment Config') {
                steps {
                    script {
                        env.CI_ENV = params.DEPLOY_ENV
                        def cfg = libraryResource("org/acme/ci/defaults-${params.DEPLOY_ENV}.yml")
                        writeFile file: 'env-config.yml', text: cfg
                        echo "Loaded configuration for ${params.DEPLOY_ENV}"
                    }
                }
            }

            stage('Version Bump') {
                steps {
                    script {
                        def versionInfo = conventionalVersion()
                        currentBuild.description = "v${versionInfo.version}"
                        env.APP_VERSION = versionInfo.version
                        echo "Computed version: ${versionInfo.version}"
                    }
                }
            }

            stage('Build') {
                steps {
                    sh 'echo "Run build here"'
                    sh 'mkdir -p dist && echo "artifact ${APP_VERSION}" > dist/app.txt'
                }
            }

            stage('Sign Artifact') {
                when {
                    expression { return params.PUBLISH_ARTIFACT }
                }
                steps {
                    signArtifact(
                        artifactPath: 'dist/app.txt',
                        gpgKeyCredentialsId: args.gpgKeyCredentialsId ?: 'gpg-private-key',
                        gpgPassphraseCredentialsId: args.gpgPassphraseCredentialsId ?: 'gpg-passphrase'
                    )
                }
            }

            stage('Credentials Health Check') {
                steps {
                    credentialsHealthCheck(
                        auditEndpoint: args.auditEndpoint ?: 'https://jenkins-audit.internal/health',
                        serviceChecks: args.serviceChecks ?: []
                    )
                }
            }

            stage('Deploy to Kubernetes') {
                when {
                    expression { return params.PUBLISH_ARTIFACT }
                }
                steps {
                    helmDeploy(
                        chartDir: env.HELM_CHART,
                        releaseName: env.HELM_RELEASE,
                        namespace: args.namespaces?.get(params.DEPLOY_ENV) ?: params.DEPLOY_ENV,
                        valuesFile: "env-${params.DEPLOY_ENV}.yaml",
                        imageTag: env.APP_VERSION,
                        kubeCredentialsId: args.kubeCredentialsId ?: "kubeconfig-${params.DEPLOY_ENV}"
                    )
                }
            }

            stage('Canary Analysis') {
                when {
                    allOf {
                        expression { return params.RUN_CANARY }
                        expression { return params.PUBLISH_ARTIFACT }
                        anyOf {
                            expression { return params.DEPLOY_ENV in ['stage', 'prod'] }
                            expression { return args.enableCanaryForDev == true }
                        }
                    }
                }
                steps {
                    canaryAnalysis(
                        serviceName: args.serviceName ?: env.APP_NAME,
                        namespace: args.namespaces?.get(params.DEPLOY_ENV) ?: params.DEPLOY_ENV,
                        canaryUrl: args.canaryUrl ?: "http://${env.APP_NAME}.${params.DEPLOY_ENV}.svc.cluster.local/health"
                    )
                }
            }
        }

        post {
            always {
                archiveArtifacts artifacts: 'dist/**, *.asc, *.sig, env-config.yml', fingerprint: true, onlyIfSuccessful: false
            }
            failure {
                echo "Pipeline failed"
            }
        }
    }
}
