    def patch = false

    commits.each { msg ->
        if (msg ==~ /.*BREAKING CHANGE.*/ || msg ==~ /^.*!:.*/) {
            major = true
        } else if (msg.startsWith('feat')) {
            minor = true
        } else if (msg.startsWith('fix') || msg.startsWith('chore') || msg.startsWith('docs') || msg.startsWith('refactor') || msg.startsWith('test')) {
            patch = true
        }
    }

    def parts = baseVersion.tokenize('.').collect { it as int }
    while (parts.size() < 3) parts << 0

    if (major) {
        parts[0] += 1; parts[1] = 0; parts[2] = 0
    } else if (minor) {
        parts[1] += 1; parts[2] = 0
    } else if (patch) {
        parts[2] += 1
    }

    return [version: "${parts[0]}.${parts[1]}.${parts[2]}"]
}
